surface.AgentRole:
export interface AgentRole {
    description: string;
    model?: string;
    name: string;
    prompt: string;
    thinkingLevel?: ThinkingLevel;
}

surface.AgentRoleProblem:
export interface AgentRoleProblem {
    file: string;
    reason: string;
}

surface.AgentRoles:
export interface AgentRoles {
    problems: AgentRoleProblem[];
    roles: AgentRole[];
}

surface.ApnsPushToken:
export interface ApnsPushToken {
    apns: string;
    environment: ApnsEnvironment;
}

surface.AvailableUpgrade:
export interface AvailableUpgrade {
    crossesMajor: boolean;
    publishedAt: number;
    version: string;
}

surface.CallMethods:
export interface CallMethods {
    abort: {
        args: {
            conversationId: ConversationId;
        };
        result: null;
    };
    addProject: {
        args: {
            path: string;
        };
        result: Project;
    };
    answer: {
        args: {
            answers: QuestionAnswer[];
            conversationId: ConversationId;
            kind: string;
            requestId: string;
        };
        result: {
            first: boolean;
        };
    };
    answerLogin: {
        args: {
            loginId: string;
            promptId: number;
            value: string;
        };
        result: null;
    };
    appendAttachment: {
        args: {
            attachmentId: string;
            data: string;
            offset: number;
        };
        result: {
            complete: boolean;
            received: number;
        };
    };
    archive: {
        args: {
            archived: boolean;
            conversationId: ConversationId;
        };
        result: null;
    };
    beginAttachment: {
        args: {
            name: string;
            size: number;
        };
        result: {
            attachmentId: string;
        };
    };
    beginLogin: {
        args: {
            method: LoginMethod;
            providerId: string;
        };
        result: {
            loginId: string;
        };
    };
    cancelLogin: {
        args: {
            loginId: string;
        };
        result: null;
    };
    cancelUpgrade: {
        args: Record<string, never>;
        result: null;
    };
    changes: {
        args: {
            conversationId: ConversationId;
        };
        result: {
            available: false;
            branch?: string;
            reason: string;
        } | {
            available: true;
            base: string;
            branch?: string;
            patch: string;
            truncated: boolean;
        };
    };
    checkUpgrade: {
        args: Record<string, never>;
        result: null;
    };
    closeTerminal: {
        args: {
            terminalId: TerminalId;
        };
        result: null;
    };
    compact: {
        args: {
            conversationId: ConversationId;
            instructions?: string;
        };
        result: {
            taskId: string;
        };
    };
    createAgent: {
        args: {
            role: AgentRole;
        };
        result: null;
    };
    createConversation: {
        args: {
            agent?: string;
            attachments?: string[];
            checkout?: "project" | "worktree";
            home: Home;
            images?: OutgoingImage[];
            model?: ModelRef;
            requestId: string;
            skills?: string[];
            text: string;
            thinkingLevel?: ThinkingLevel;
        };
        result: {
            conversationId: ConversationId;
        };
    };
    createPairing: {
        args: Record<string, never>;
        result: {
            expiresAt: number;
            url: string;
        };
    };
    deleteAgent: {
        args: {
            name: string;
        };
        result: null;
    };
    earlierEntries: {
        args: {
            before: EntryId;
            conversationId: ConversationId;
            limit: number;
        };
        result: TranscriptPage;
    };
    fork: {
        args: {
            conversationId: ConversationId;
            entryId: string;
            removeTools?: string[];
        };
        result: {
            conversationId: ConversationId;
        };
    };
    image: {
        args: {
            ref: string;
            variant?: "preview" | "thumbnail";
        };
        result: ImageResult;
    };
    listCommands: {
        args: {
            conversationId: ConversationId;
        };
        result: CommandListing;
    };
    listEndpointModels: {
        args: {
            api: CustomProviderApi;
            apiKey?: string;
            baseUrl: string;
            providerId?: string;
        };
        result: {
            models: string[];
        };
    };
    listFiles: {
        args: {
            query: string;
            scope: FileScope;
        };
        result: FileListing;
    };
    listFolders: {
        args: {
            path?: string;
        };
        result: FolderListing;
    };
    listSkills: {
        args: {
            scope: SkillScope;
        };
        result: SkillListing;
    };
    logout: {
        args: {
            providerId: string;
        };
        result: null;
    };
    openTerminal: {
        args: {
            cols: number;
            conversationId: ConversationId;
            rows: number;
        };
        result: {
            terminalId: TerminalId;
        };
    };
    ping: {
        args: {
            id: string;
        };
        result: {
            id: string;
        };
    };
    removeCustomProvider: {
        args: {
            providerId: string;
        };
        result: null;
    };
    removeProject: {
        args: {
            path: string;
        };
        result: null;
    };
    renameConversation: {
        args: {
            conversationId: ConversationId;
            title: string;
        };
        result: null;
    };
    renameTerminal: {
        args: {
            name: null | string;
            terminalId: TerminalId;
        };
        result: null;
    };
    reorderQueued: {
        args: {
            before?: number;
            conversationId: ConversationId;
            submissionId: number;
        };
        result: {
            outcome: "moved" | "sent" | "unavailable";
        };
    };
    resizeTerminal: {
        args: {
            cols: number;
            rows: number;
            terminalId: TerminalId;
        };
        result: null;
    };
    restartTerminal: {
        args: {
            cols: number;
            rows: number;
            terminalId: TerminalId;
        };
        result: null;
    };
    revokeDevice: {
        args: {
            publicKey: string;
        };
        result: null;
    };
    rtcOffer: {
        args: RtcOfferArgs;
        result: RtcAnswer;
    };
    runCommand: {
        args: {
            args?: string;
            conversationId: ConversationId;
            name: string;
        };
        result: null;
    };
    saveCustomProvider: {
        args: {
            apiKey?: null | string;
            provider: CustomProviderInput;
        };
        result: null;
    };
    setAgent: {
        args: {
            agent: null | string;
            conversationId: ConversationId;
        };
        result: null;
    };
    setModel: {
        args: {
            conversationId: ConversationId;
            model: ModelRef;
        };
        result: null;
    };
    setPushToken: {
        args: {
            token: PushToken | null;
        };
        result: null;
    };
    setThinkingLevel: {
        args: {
            conversationId: ConversationId;
            level: ThinkingLevel;
        };
        result: null;
    };
    startUpgrade: {
        args: {
            when: UpgradeWhen;
        };
        result: null;
    };
    steerQueued: {
        args: {
            conversationId: ConversationId;
            submissionId: number;
        };
        result: {
            outcome: "sent" | "steered" | "unavailable";
        };
    };
    stopProcess: {
        args: {
            conversationId: ConversationId;
            id: ProcessId;
        };
        result: {
            state: ProcessState;
        };
    };
    submission: {
        args: {
            conversationId: ConversationId;
            requestId: string;
        };
        result: null | {
            entry?: number;
            status: "done" | "placed" | "queued" | "unanswered";
            submissionId: number;
        };
    };
    submit: {
        args: {
            attachments?: string[];
            conversationId: ConversationId;
            images?: OutgoingImage[];
            requestId: string;
            skills?: string[];
            text: string;
            whenBusy: "followUp" | "steer";
        };
        result: {
            entry?: number;
            submissionId: number;
        };
    };
    terminalInput: {
        args: {
            data: string;
            terminalId: TerminalId;
        };
        result: null;
    };
    updateAgent: {
        args: {
            role: AgentRole;
        };
        result: null;
    };
    updateSettings: {
        args: {
            patch: HostSettingsPatch;
        };
        result: null;
    };
    withdrawQueued: {
        args: {
            conversationId: ConversationId;
            submissionId: number;
        };
        result: {
            outcome: "sent" | "withdrawn";
        };
    };
}

surface.ClientFrame:
export type ClientFrame = {
    [M in CallMethod]: {
        args: CallMethods[M]["args"];
        id: number;
        method: M;
        type: "call";
    };
}[CallMethod] | {
    images?: "ref";
    since?: number;
    stream: StreamName;
    type: "subscribe";
    window?: TranscriptWindow;
} | {
    stream: StreamName;
    type: "unsubscribe";
};

surface.CodemodeCallSchema:
export const CodemodeCallSchema = Type.Object({
    args: Type.String(),
    details: Type.Optional(Type.Unknown()),
    durationMs: Type.Optional(Type.Number()),
    error: Type.Optional(Type.String()),
    id: Type.Optional(Type.Number()),
    name: Type.String(),
    status: Type.Union([Type.Literal("cancelled"), Type.Literal("error"), Type.Literal("ok"), Type.Literal("running")]),
});

surface.CommandInfo:
export interface CommandInfo {
    argumentHint?: string;
    description: string;
    disabled?: string;
    name: string;
    source: "builtin" | "plugin";
}

surface.ConversationDefaults:
export interface ConversationDefaults {
    model?: ModelRef;
    thinkingLevel?: ThinkingLevel;
}

surface.ConversationSummary:
export interface ConversationSummary {
    activity?: {
        target?: string;
        tool: string;
    };
    currentAgent?: null | string;
    forkedAt?: string;
    id: ConversationId;
    kind: "conversation" | "fork" | "subagent";
    label?: string;
    lifecycle?: "background" | "foreground";
    model?: ModelRef;
    parent?: ConversationId;
    role?: string;
    status?: "failed" | "needs-answer" | "running";
    title?: string;
    updatedAt?: number;
}

surface.CustomProvider:
export interface CustomProvider {
    api: CustomProviderApi;
    baseUrl: string;
    models: string[];
}

surface.CustomProviderInput:
export interface CustomProviderInput extends CustomProvider {
    id: string;
    name: string;
}

surface.DeviceEntry:
export type DeviceEntry = {
    name: string;
    pairedAt: number;
    publicKey: string;
    source?: DeviceSource;
};

surface.EndpointSet:
export interface EndpointSet {
    endpoints: HostEndpoint[];
    schemaVersion: typeof ENDPOINT_SET_SCHEMA_VERSION;
}

surface.FileListing:
export interface FileListing {
    files: string[];
    truncated: boolean;
}

surface.FileScope:
export type FileScope = {
    conversationId: ConversationId;
    kind: "conversation";
} | {
    checkout: "project" | "worktree";
    kind: "project";
    path: string;
};

surface.FolderListing:
export interface FolderListing {
    folders: {
        name: string;
        path: string;
    }[];
    home: string;
    path: string;
}

surface.Home:
export type Home = {
    kind: "chat";
} | {
    kind: "project";
    path: string;
};

surface.HostEndpoint:
export interface HostEndpoint {
    role: HostEndpointRole;
    transport: "webSocket";
    url: string;
}

surface.HostIndex:
export type HostIndex = {
    checkouts?: WorktreeCheckout[];
    conversations: IndexEntry[];
    projects: Project[];
};

surface.HostProviders:
export interface HostProviders {
    logins: LoginFlow[];
    providers: ProviderInfo[];
}

surface.HostSettings:
export interface HostSettings {
    acceptAccountDevices: boolean;
    autoUpgrade?: AutoUpgradeMode;
    custom: HostSettingKey[];
    defaultModel: ModelRef | null;
    defaultThinkingLevel: ThinkingLevel | null;
    followUpMode: QueueMode;
    hostName?: string;
    rtcStun?: string[];
    steeringMode: QueueMode;
}

surface.HostSettingsPatch:
export type HostSettingsPatch = {
    [K in HostSettingKey]?: Exclude<HostSettings[K], null> | null;
};

surface.HostStreamValues:
export interface HostStreamValues {
    agents: AgentRoles;
    auth: HostAuth;
    conversations: ConversationSummary[];
    devices: HostDevices;
    index: HostIndex;
    mcp: McpStatus | null;
    models: ModelSummary[];
    providers: HostProviders;
    settings: HostSettings;
    upgrade: HostUpgrade;
}

surface.HostUpgrade:
export interface HostUpgrade {
    attempt: number;
    available: AvailableUpgrade | null;
    blocked: UpgradeBlocker | null;
    checkError: null | string;
    checkedAt: null | number;
    checking: boolean;
    current: null | string;
    failure: null | {
        attempt: number;
        message: string;
        version: string;
    };
    phase: UpgradePhase;
    target: null | string;
}

surface.ImageResult:
export type ImageResult = MessageImage & {
    variant?: ImageVariant;
};

surface.IndexEntry:
export type IndexEntry = {
    archived?: boolean;
    createdAt: number;
    home: Home;
    id: ConversationId;
    requestId?: string;
    role?: string;
};

surface.LoginEvent:
export type LoginEvent = {
    expiresAt?: number;
    type: "device_code";
    userCode: string;
    verificationUri: string;
} | {
    instructions?: string;
    type: "auth_url";
    url: string;
} | {
    links?: {
        label?: string;
        url: string;
    }[];
    message: string;
    type: "info";
} | {
    message: string;
    type: "progress";
};

surface.LoginFlow:
export interface LoginFlow {
    error?: string;
    events: LoginEvent[];
    id: string;
    method: LoginMethod;
    prompt?: LoginPrompt;
    providerId: string;
    state: "cancelled" | "failed" | "running" | "succeeded";
}

surface.LoginPrompt:
export type LoginPrompt = {
    id: number;
} & ({
    message: string;
    options: {
        description?: string;
        id: string;
        label: string;
    }[];
    type: "select";
} | {
    message: string;
    placeholder?: string;
    type: "manual_code" | "secret" | "text";
});

surface.McpServerStatus:
export interface McpServerStatus {
    error?: string;
    name: string;
    state: "connected" | "connecting" | "disabled" | "failed";
    tools: number;
}

surface.McpStatus:
export interface McpStatus {
    configPath: string;
    errors: string[];
    servers: McpServerStatus[];
}

surface.MessageImage:
export type MessageImage = {
    data: string;
    mimeType: ImageMimeType;
};

surface.ModelSummary:
export interface ModelSummary extends ModelRef {
    contextWindow: number;
    images?: boolean;
    name: string;
    thinkingLevels: ThinkingLevel[];
}

surface.Notice:
export interface Notice {
    id: number;
    level: "error" | "info" | "warning";
    message: string;
}

surface.OutgoingImage:
export type OutgoingImage = MessageImage | {
    ref: string;
};

surface.ProcessExited:
export type ProcessExited = {
    exited: null | number;
    signal?: string;
};

surface.ProcessInfoSchema:
export const ProcessInfoSchema = Type.Object({
    command: Type.String(),
    endedAt: Type.Optional(Type.Number()),
    id: Type.String({ minLength: 1 }),
    name: Type.String(),
    owner: Type.Number(),
    pid: Type.Optional(Type.Number()),
    startedAt: Type.Number(),
    state: ProcessStateSchema,
});

surface.ProcessStateSchema:
export const ProcessStateSchema = Type.Union([
    Type.Literal("lost"),
    Type.Literal("running"),
    Type.Literal("starting"),
    Type.Object({
        exited: Type.Union([Type.Null(), Type.Number()]),
        signal: Type.Optional(Type.String()),
    }),
    Type.Object({
        stopped: Type.Union([
            Type.Literal("agent"),
            Type.Literal("archive"),
            Type.Literal("shutdown"),
            Type.Literal("user"),
        ]),
    }),
    Type.Object({ failed: Type.String() }),
]);

surface.Project:
export type Project = {
    addedAt: number;
    name: string;
    path: string;
};

surface.ProtocolVersion:
export interface ProtocolVersion {
    major: number;
    minor: number;
}

surface.ProviderInfo:
export interface ProviderInfo {
    ambient?: string;
    apiKey?: {
        name: string;
    };
    custom?: CustomProvider;
    id: string;
    name: string;
    oauth?: {
        loginLabel?: string;
        name: string;
        subscription: boolean;
    };
    stored?: {
        kind: LoginMethod;
        subscription: boolean;
    };
}

surface.QuestionAnswerSchema:
export const QuestionAnswerSchema = Type.Object({
    other: Type.Optional(Type.String()),
    selected: Type.Array(Type.String()),
});

surface.QuestionItemSchema:
export const QuestionItemSchema = Type.Object({
    header: Type.String({ maxLength: 16, minLength: 1 }),
    multiSelect: Type.Optional(Type.Boolean()),
    options: Type.Array(QuestionOptionSchema, { maxItems: 4, minItems: 2 }),
    question: Type.String({ minLength: 1 }),
});

surface.QuestionOptionSchema:
export const QuestionOptionSchema = Type.Object({
    description: Type.Optional(Type.String()),
    label: Type.String({ minLength: 1 }),
});

surface.QuestionRequestSchema:
export const QuestionRequestSchema = Type.Object({
    askedAt: Type.Number(),
    id: Type.String({ minLength: 1 }),
    questions: Type.Array(QuestionItemSchema, { maxItems: 4, minItems: 1 }),
    resolution: Type.Optional(QuestionResolutionSchema),
});

surface.QuestionResolutionSchema:
export const QuestionResolutionSchema = Type.Union([
    Type.Object({ answers: Type.Array(QuestionAnswerSchema), at: Type.Number(), outcome: Type.Literal("answered") }),
    Type.Object({ at: Type.Number(), outcome: Type.Literal("cancelled") }),
    Type.Object({ at: Type.Number(), outcome: Type.Literal("dismissed") }),
]);

surface.RtcHello:
export interface RtcHello {
    signalOnly: true;
    stun: string[];
}

surface.RtcOfferArgs:
export interface RtcOfferArgs {
    attempt: string;
    sdp: string;
}

surface.ServerFrame:
export type ServerFrame = {
    protocol: ProtocolVersion;
    rtc?: RtcHello;
    type: "signalHello";
} | {
    defaults?: ConversationDefaults;
    docs: {
        kind: string;
        presentation?: PresentationType;
    }[];
    endpointSet?: EndpointSet;
    hostVersion?: string;
    models: ModelSummary[];
    processes?: ProcessesHello;
    protocol: ProtocolVersion;
    rtc?: RtcHello;
    session: SessionInfo;
    terminals?: TerminalsHello;
    toolPresentations: Record<string, PresentationType>;
    type: "hello";
} | {
    data: string;
    reset?: true;
    seq: number;
    stream: `process:${ProcessId}` | `terminal:${TerminalId}`;
    type: "output";
} | {
    reason: string;
    stream: StreamName;
    type: "ended";
} | {
    level: Notice["level"];
    message: string;
    type: "notice";
} | {
    ops: Op[];
    stream: StreamName;
    type: "ops";
} | {
    error: string;
    id: number;
    ok: false;
    type: "result";
} | {
    id: number;
    ok: true;
    type: "result";
    value: unknown;
} | {
    stream: StreamName;
    type: "snapshot";
    value: unknown;
};

surface.SessionInfo:
export interface SessionInfo {
    directory: string;
    id: string;
}

surface.SkillListing:
export interface SkillListing {
    skills: {
        description: string;
        name: string;
        source: "project" | "user";
    }[];
}

surface.SkillScope:
export type SkillScope = {
    kind: "chat";
} | {
    conversationId: ConversationId;
    kind: "conversation";
} | {
    checkout: "project" | "worktree";
    kind: "project";
    path: string;
};

surface.StoredLogin:
export interface StoredLogin {
    kind: "api_key" | "oauth";
    name: string;
    providerId: string;
    subscription: boolean;
}

surface.TodoItemSchema:
export const TodoItemSchema = Type.Object({
    status: Type.Union([Type.Literal("completed"), Type.Literal("in_progress"), Type.Literal("pending")]),
    text: Type.String({ minLength: 1 }),
});

surface.TranscriptPage:
export interface TranscriptPage {
    before?: EntryId;
    entries: EntryRecord[];
}

surface.TranscriptWindow:
export interface TranscriptWindow {
    from?: EntryId;
    limit: number;
}

surface.WorktreeCheckout:
export type WorktreeCheckout = {
    base: string;
    branch: string;
    conversationId: ConversationId;
    path: string;
    repo: string;
    snapshot?: string;
    subdir: string;
};
